#!/bin/sh
D="$(dirname "$0")/.."
echo "$*" >> "$D/calls.log"
case "$1" in
  image)
    case "$4" in
      '{{.Id}}') echo sha256:fx ;;
      '{{.Created}}') echo 2026-01-02T03:04:05+09:00 ;;
      '{{json .Config.Env}}') cat "$D/img_env.json" ;;
      *) exit 1 ;;
    esac ;;
  history)
    if [ "$4" = '{{json .}}' ]; then cat "$D/hist.jsonl"; else cat "$D/hist.txt"; fi ;;
  create) echo cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc ;;
  cp)
    shift; [ "$1" = "-L" ] && shift
    src="${1#*:}"; dest="$2"
    if [ -d "$D/img$src" ]; then cp -r "$D/img$src" "$dest"
    elif [ -f "$D/img$src" ]; then cp "$D/img$src" "$dest"
    else echo "Error response from daemon: Could not find the file $src in container x" >&2; exit 1; fi ;;
  rm) echo "$3" ;;
  *) echo "unexpected docker call" >&2; exit 1 ;;
esac

